// SCENARIO — the whole test harness is `gv.assert`: it throws on the first
// failure, so silence is a pass. Run it from the Scripts view, or with
//
//   grpcview script run smoke --collection example
//
// Every request it drives is a SAVED one, invoked through the same pipeline the
// UI uses — bodies, metadata, folder inheritance and middleware all included.

const json = await gv.invoke("Echo/Unary (JSON)");
gv.assert("plain protojson body invokes", json.ok);
gv.assert("the server echoes the message back", json.body.message === "echo: hello");

// The second argument of gv.invoke lands in the target's gv.request.params.
const params = await gv.invoke("Echo/Unary (params)", { message: "from the scenario" });
gv.assert("params reach the target's body", params.body.message === "echo: from the scenario");

// Folder metadata is inherited even though this request never spreads it itself.
gv.assert(
  "the Echo folder's metadata is inherited",
  json.requestMetadata["x-demo-suite"][0] === "echo",
);

// Generators compose: this body and its metadata both call them.
const generated = await gv.invoke("Echo/Unary (generators)");
gv.assert(
  "the generator-built id is echoed",
  /^echo: echo_[0-9a-f]{12} at /.test(generated.body.message),
);
gv.assert(
  "dayjs runs on the sandbox's pinned clock",
  generated.requestMetadata["x-sent-at"][0] === "2022-01-01T00:00:00Z",
);

// Middleware runs last, on the already-serialised message.
const traced = await gv.invoke("Echo/Unary (middleware)");
gv.assert(
  "middleware rewrote the body",
  traced.body.message === "echo: [traced] before middleware",
);
gv.assert("middleware stamped a trace id", traced.requestMetadata["x-trace-id"][0].length > 0);

// gv.invoke chains: this one invokes a request that itself invokes another.
const described = await gv.invoke("Collections/DescribeMethod");
gv.assert("grpcview can describe its own bazel-built echo proto", described.ok);
gv.assert(
  "the descriptor kept the .proto doc comments",
  described.body.protoText.includes("the request message"),
);

"10 assertions passed"
